(()=>{"use strict";class t extends HTMLElement{connectedCallback(){this.innerHTML='\n            <div style="padding:20px;">\n                <h2>Contact Terminator</h2>\n\n                <button id="refreshBtn">\n                    Refresh Contacts\n                </button>\n\n                <table id="contactsTable" style="width:100%;margin-top:20px;">\n                    <thead>\n                        <tr>\n                            <th>Select</th>\n                            <th>Queue</th>\n                            <th>ANI</th>\n                            <th>Wait Time</th>\n                            <th>Interaction ID</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                    </tbody>\n                </table>\n\n                <button id="terminateBtn"\n                        style="margin-top:20px;">\n                    Terminate Selected\n                </button>\n            </div>\n        '}}customElements.define("contact-terminator",t)})();